import datetime
import hashlib
import json
import os
from pathlib import Path
import platform
import re
import signal
import stat
import time

LIMIT = 4096
TIMEOUT = 1.0
out = {'schema_version': 1, 'capture_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
       'kernel_release': platform.release(),
       'scope': 'fixed cached WLAN firmware/BDF descriptor sysfs only; no radio or logging controls',
       'read_limit_bytes': LIMIT, 'per_operation_timeout_seconds': TIMEOUT,
       'discovery': {}, 'versions': {}, 'device_mutated': False, 'radio_restarted': False,
       'qmi_query_sent': False, 'mmio_read': False, 'raw_logs_read': False,
       'qmi_board_id_observed': False, 'selected_bdf_filename': None}

def alarm(_number, _frame):
    raise TimeoutError('bounded metadata operation exceeded one second')
signal.signal(signal.SIGALRM, alarm)

def bounded(action):
    signal.setitimer(signal.ITIMER_REAL, TIMEOUT)
    try:
        return action()
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)

def directories(path, allowed, maximum):
    def inspect():
        if not stat.S_ISDIR(path.lstat().st_mode):
            raise ValueError('metadata parent is not a real directory')
        names = []
        with os.scandir(path) as iterator:
            for index, entry in enumerate(iterator):
                if index >= maximum:
                    raise ValueError('directory count exceeds bound')
                if allowed.fullmatch(entry.name):
                    names.append(entry.name)
        return sorted(names)
    try:
        names = bounded(inspect)
        out['discovery'][str(path)] = {'matched_names_only': names, 'status': 'read'}
        return names
    except (OSError, ValueError, TimeoutError) as exc:
        out['discovery'][str(path)] = {'status': 'unavailable', 'reason': type(exc).__name__}
        return []

roots = directories(Path('/sys/kernel'), re.compile(r'(?:wifi|wlan)[A-Za-z0-9_.-]{0,32}'), 1024)
format_re = re.compile(r'FW:(\d+)\.(\d+)\.(\d+)\.(\d+)\.(\d+)\.(\d+) HW:([A-Za-z0-9._ +()/:-]{1,128}) Board version: ([0-9a-fA-F]{1,8}) Ref design id: ([0-9a-fA-F]{1,8}) Customer id: ([0-9a-fA-F]{1,8}) Project id: ([0-9a-fA-F]{1,8}) Board Data Rev: ([0-9a-fA-F]{1,8})')
for root_name in roots:
    parent = Path('/sys/kernel') / root_name
    names = directories(parent, re.compile(r'wlan'), 64)
    if 'wlan' not in names:
        continue
    wlan = parent / 'wlan'
    names = directories(wlan, re.compile(r'fw|driver_version'), 64)
    if 'fw' not in names:
        continue
    fw = wlan / 'fw'
    ids = directories(fw, re.compile(r'[0-9]{1,5}'), 16)
    for identity in ids:
        directory = fw / identity
        names = directories(directory, re.compile(r'version'), 16)
        if 'version' not in names:
            continue
        path = directory / 'version'
        started = time.monotonic()
        def read_version():
            fd = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW | os.O_NONBLOCK)
            try:
                if not stat.S_ISREG(os.fstat(fd).st_mode):
                    raise ValueError('not a metadata regular file')
                data = os.read(fd, LIMIT + 1)
                if len(data) > LIMIT:
                    raise ValueError('metadata exceeds byte bound')
                return data
            finally:
                os.close(fd)
        try:
            data = bounded(read_version)
            record = {'size_bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest(),
                      'elapsed_seconds': time.monotonic() - started}
            text = data.decode('ascii', errors='replace')
            parsed = {}
            fw_match = re.search(r'(?<![A-Za-z])FW\s*:\s*([0-9]+(?:\.[0-9]+){2,7})(?=\s|$)', text)
            if fw_match:
                parsed['firmware_version_components'] = [int(value) for value in fw_match.group(1).split('.')]
            descriptors = {}
            for label, key in [('Board version', 'bdf_version'), ('Ref design id', 'ref_design_id'),
                               ('Customer id', 'customer_id'), ('Project id', 'project_id'),
                               ('Board Data Rev', 'board_data_rev')]:
                match = re.search(re.escape(label) + r'\s*:\s*(?:0[xX])?([0-9a-fA-F]{1,8})(?=\s|$)', text)
                if match:
                    descriptors[key] = '0x' + match.group(1).lower()
            if descriptors:
                parsed['bdf_descriptor_hex'] = descriptors
            hardware = re.search(r'(?<![A-Za-z])HW\s*:\s*([A-Za-z][A-Za-z0-9._() /+-]{0,96}?)\s+Board version\s*:', text)
            if hardware:
                parsed['hardware_name'] = hardware.group(1).strip()
            record.update(parsed)
            record.update(status='parsed_cached_metadata' if descriptors else 'no_named_bdf_descriptors',
                          extraction='allowlisted field names only; no whole-line publication',
                          other_contents_omitted=True,
                          all_five_bdf_descriptor_fields_present=len(descriptors) == 5)
            out['versions'][str(path)] = record
        except (OSError, ValueError, TimeoutError) as exc:
            out['versions'][str(path)] = {'status': 'unavailable', 'reason': type(exc).__name__,
                                         'elapsed_seconds': time.monotonic() - started}
out['status'] = ('cached_bdf_descriptors_observed' if any(v['status'] == 'parsed_cached_metadata' for v in out['versions'].values())
                 else 'no_parsed_cached_version_in_fixed_discovery')
out['limits'] = ['BDF descriptor fields are not the CNSS QMI board_id and do not select a stock bdwlan candidate by themselves.',
                 'A bounded metadata read establishes no association, throughput, firmware authentication or native Linux operation.',
                 'Public source is a pinned interface clue, not a byte-equivalent identification of the shipping Android binary.']
print(json.dumps(out, indent=2, sort_keys=True))

